typedef enum { SUIT_CLUBS, SUIT_DIAMONDS, SUIT_HEARTS, SUIT_SPADES } suit_t;

const char *suit_to_string(suit_t s);              /* one formatting point */
int suit_from_string(const char *s, suit_t *out);  /* validates; 0 = ok */

/* internal switches stay exhaustive and never use default: */
switch (s) {
case SUIT_CLUBS:    return "clubs";
case SUIT_DIAMONDS: return "diamonds";
case SUIT_HEARTS:   return "hearts";
case SUIT_SPADES:   return "spades";
}
